import{_ as t,o,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/slides/style-and-arrange-crop.png",u=JSON.parse('{"title":"Style and arrange objects","description":"Change how shapes, images, and text boxes look, and place, align, group, and order them on a slide.","frontmatter":{"title":"Style and arrange objects","description":"Change how shapes, images, and text boxes look, and place, align, group, and order them on a slide.","type":"how-to"},"headers":[],"relativePath":"slides/style-and-arrange.md","filePath":"slides/style-and-arrange.md"}'),n={name:"slides/style-and-arrange.md"};function i(l,e,d,h,c,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="style-and-arrange-objects" tabindex="-1">Style and arrange objects <a class="header-anchor" href="#style-and-arrange-objects" aria-label="Permalink to &quot;Style and arrange objects&quot;">​</a></h1><p>Change the fill, border, and effects of objects on a slide, and place them exactly where you want them.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. A share-link viewer can&#39;t change the deck.</li><li>On a phone, styling controls are in the <strong>Format</strong> sheet. See <a href="#on-a-phone">On a phone</a>.</li></ul></div><h2 id="select-objects" tabindex="-1">Select objects <a class="header-anchor" href="#select-objects" aria-label="Permalink to &quot;Select objects&quot;">​</a></h2><ul><li>Click an object to select it. Hold <code>Shift</code> and click to add or remove objects.</li><li>Drag across an empty part of the slide to select every object the box touches.</li><li>Press <code>⌘+A</code> / <code>Ctrl+A</code> to select everything on the slide, and <code>Tab</code> to step through objects one at a time.</li></ul><p>To select one object inside a group, double-click it. Press <code>Escape</code> to step back out to the whole group.</p><h2 id="change-the-fill" tabindex="-1">Change the fill <a class="header-anchor" href="#change-the-fill" aria-label="Permalink to &quot;Change the fill&quot;">​</a></h2><ol><li>Select a shape or text box.</li><li>Click <strong>Fill color</strong> in the toolbar.</li><li>Choose a theme color, a standard color, or a custom color. Use the <strong>Transparency</strong> slider to make it see-through. For a shape, these are on the <strong>Solid</strong> tab.</li></ol><p>Theme colors follow the deck: if you later switch themes, the object switches color with it.</p><h3 id="use-a-gradient" tabindex="-1">Use a gradient <a class="header-anchor" href="#use-a-gradient" aria-label="Permalink to &quot;Use a gradient&quot;">​</a></h3><ol><li>Select a shape and click <strong>Fill color</strong>.</li><li>Click the <strong>Gradient</strong> tab.</li><li>Click the stops bar to add a stop, drag a stop to move it, and select a stop to change its color or <strong>Position</strong>. Click <strong>Delete stop</strong> to remove the selected one.</li><li>Choose one of the eight direction arrows, or type an <strong>Angle</strong>.</li></ol><p>Gradients are linear and are available for shapes only.</p><h2 id="change-the-border" tabindex="-1">Change the border <a class="header-anchor" href="#change-the-border" aria-label="Permalink to &quot;Change the border&quot;">​</a></h2><ol><li>Select a shape, text box, or line.</li><li>Use the border controls in the toolbar: <ul><li><strong>Border color</strong> sets the color.</li><li><strong>Border weight</strong> sets the thickness, from <strong>No border</strong> to 16 px.</li><li><strong>Border dash</strong> sets solid, dashed, or dotted.</li></ul></li></ol><h2 id="copy-formatting-to-another-object" tabindex="-1">Copy formatting to another object <a class="header-anchor" href="#copy-formatting-to-another-object" aria-label="Permalink to &quot;Copy formatting to another object&quot;">​</a></h2><ol><li>Select one shape, text box, or line.</li><li>Click <strong>Format painter</strong> (the brush icon) in the toolbar.</li><li>Click the object you want to change.</li></ol><p>The fill and border copy once, then the painter turns off. To cancel before you click, press <code>Escape</code> or click <strong>Format painter</strong> again.</p><h2 id="crop-an-image" tabindex="-1">Crop an image <a class="header-anchor" href="#crop-an-image" aria-label="Permalink to &quot;Crop an image&quot;">​</a></h2><ol><li>Double-click the image, or select it and click <strong>Crop</strong> in the toolbar.</li><li>Drag the black handles to trim the edges. Drag inside the crop window to move the picture under it.</li><li>Press <code>Enter</code>, click <strong>Done cropping</strong>, or click outside the image to apply. Press <code>Escape</code> to cancel.</li></ol><p>To return to the full picture, select the image and click <strong>Reset crop</strong>. It is unavailable until the image has been cropped.</p><p><img src="'+s+'" alt="Image in crop mode with the area outside the crop window dimmed and eight black handles"></p><h2 id="use-the-format-options-panel" tabindex="-1">Use the Format options panel <a class="header-anchor" href="#use-the-format-options-panel" aria-label="Permalink to &quot;Use the Format options panel&quot;">​</a></h2><ol><li>Select an object. With nothing selected, the panel shows the deck&#39;s slide size.</li><li>Click <strong>Format</strong> at the right end of the toolbar (on a narrow window, the icon with the tooltip <strong>Format options</strong>).</li><li>Change the values. To add a <strong>Drop shadow</strong> or <strong>Reflection</strong>, select its checkbox to show its settings.</li></ol><p>The panel shows only the sections that apply to what you selected:</p><table tabindex="0"><thead><tr><th>Section</th><th>Appears for</th><th>Settings</th></tr></thead><tbody><tr><td><strong>Size &amp; Position</strong></td><td>Every object</td><td>Width, Height, X position, Y position, Rotation, <strong>Lock aspect ratio</strong>, 90° rotate buttons, and <strong>Units</strong> (Inches or Centimeters)</td></tr><tr><td><strong>Text fitting</strong></td><td>Text boxes</td><td><strong>Do not autofit</strong>, <strong>Shrink text on overflow</strong>, or <strong>Resize shape to fit text</strong></td></tr><tr><td><strong>Recolor</strong></td><td>Images</td><td><strong>No recolor</strong>, <strong>Grayscale</strong>, or <strong>Sepia</strong></td></tr><tr><td><strong>Adjustments</strong></td><td>Images</td><td>Transparency, Brightness, Contrast</td></tr><tr><td><strong>Drop shadow</strong></td><td>Shapes, images, text boxes</td><td>Color, Transparency, Angle, Distance, Blur</td></tr><tr><td><strong>Reflection</strong></td><td>Shapes, images, text boxes</td><td>Transparency, Distance, Size</td></tr><tr><td><strong>Alt text</strong></td><td>Shapes, images, text boxes, tables</td><td>A description for screen readers</td></tr></tbody></table><p>Lines, groups, and mixed selections show <strong>Size &amp; Position</strong> only. Lines and mixed selections have no Width, Height, or Rotation. A text box set to <strong>Resize shape to fit text</strong> has its Height locked, because the text sets it. <strong>Units</strong> applies to the whole deck and also sets the rulers.</p><h3 id="change-the-slide-size" tabindex="-1">Change the slide size <a class="header-anchor" href="#change-the-slide-size" aria-label="Permalink to &quot;Change the slide size&quot;">​</a></h3><ol><li>Click an empty part of the slide so nothing is selected.</li><li>In the Format options panel, choose <strong>Widescreen 16:9</strong>, <strong>Standard 4:3</strong>, or <strong>Widescreen 16:10</strong>.</li></ol><p>To use another shape, type a <strong>Height</strong>. Width stays fixed, and the preset reads <strong>Custom</strong>.</p><h2 id="align-and-distribute-objects" tabindex="-1">Align and distribute objects <a class="header-anchor" href="#align-and-distribute-objects" aria-label="Permalink to &quot;Align and distribute objects&quot;">​</a></h2><ol><li>Select the objects. With one object selected, it aligns to the slide.</li><li>Click <strong>Arrange</strong> (the stacked-layers icon) in the toolbar.</li><li>Select <strong>Align</strong> and choose <strong>Left</strong>, <strong>Center</strong>, <strong>Right</strong>, <strong>Top</strong>, <strong>Middle</strong>, or <strong>Bottom</strong>.</li></ol><p>To even out the gaps, select three or more objects and choose <strong>Arrange &gt; Distribute &gt; Horizontally</strong> or <strong>Vertically</strong>. The outermost two stay put.</p><h2 id="change-the-stacking-order" tabindex="-1">Change the stacking order <a class="header-anchor" href="#change-the-stacking-order" aria-label="Permalink to &quot;Change the stacking order&quot;">​</a></h2><ol><li>Select an object.</li><li>Choose <strong>Arrange &gt; Order</strong> and select <strong>Bring to front</strong>, <strong>Bring forward</strong>, <strong>Send backward</strong>, or <strong>Send to back</strong>.</li></ol><p>You can also right-click the object for the same items.</p><h2 id="group-and-ungroup-objects" tabindex="-1">Group and ungroup objects <a class="header-anchor" href="#group-and-ungroup-objects" aria-label="Permalink to &quot;Group and ungroup objects&quot;">​</a></h2><ol><li>Select two or more objects.</li><li>Choose <strong>Arrange &gt; Group</strong>, or press <code>⌘+Option+G</code> / <code>Ctrl+Alt+G</code>.</li></ol><p>To break a group apart, select it and choose <strong>Arrange &gt; Ungroup</strong>.</p><h2 id="rotate-an-object" tabindex="-1">Rotate an object <a class="header-anchor" href="#rotate-an-object" aria-label="Permalink to &quot;Rotate an object&quot;">​</a></h2><ul><li>Drag the handle above the object. Hold <code>Shift</code> to snap to 15° steps.</li><li>Or choose <strong>Arrange &gt; Rotate 90° clockwise</strong> or <strong>Rotate 90° counter-clockwise</strong>.</li></ul><h2 id="place-objects-precisely" tabindex="-1">Place objects precisely <a class="header-anchor" href="#place-objects-precisely" aria-label="Permalink to &quot;Place objects precisely&quot;">​</a></h2><ul><li>Press the arrow keys to nudge the selection by 1 px, or <code>Shift</code> plus an arrow key for 10 px.</li><li>Hold <code>Shift</code> while dragging to move along one axis only.</li><li>Hold <code>Shift</code> while resizing to keep the proportions.</li></ul><p>As you drag, objects snap to the slide center, to guides, and to the edges of other objects. Red guides appear when gaps or sizes match a nearby object. Snapping and these guides are always on.</p><h3 id="add-a-guide" tabindex="-1">Add a guide <a class="header-anchor" href="#add-a-guide" aria-label="Permalink to &quot;Add a guide&quot;">​</a></h3><ol><li>Press on the ruler along the top or left of the slide.</li><li>Drag onto the slide and release.</li></ol><p>Drag a guide to move it, or drag it back onto the ruler to delete it. Right-click a guide for <strong>Delete guide</strong>, <strong>Delete all vertical guides</strong> or <strong>Delete all horizontal guides</strong>, and <strong>Delete all guides</strong>. Guides apply to every slide in the deck.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><ul><li>Select an object, then tap <strong>Format</strong> in the toolbar for its fill, border, and image controls.</li><li>Tap <strong>Arrange</strong> (the stacked-layers icon) for align, order, group, and rotate.</li><li>For the Format options panel, tap <strong>More slide options</strong> (⋮) and select <strong>Format options…</strong>. It opens as a sheet.</li></ul><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>The format painter has no stay-on mode and no shortcut. It can&#39;t copy from an image, and lines copy only onto other lines.</li><li>Painting a gradient onto a text box keeps one solid color.</li><li>Crop is a free rectangle. There are no aspect-ratio presets or crop-to-shape.</li><li>Images inside a group can&#39;t be cropped. Ungroup them first.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/slides/add-content.html">Add content</a> to insert shapes, images, and tables.</li><li><a href="/docs/slides/themes-and-layouts.html">Themes and layouts</a> to change the colors that theme fills use.</li><li><a href="/docs/slides/keyboard-shortcuts.html">Keyboard shortcuts</a> for selection, nudge, and order shortcuts.</li></ul>',52)])])}const b=t(n,[["render",i]]);export{u as __pageData,b as default};
